namespace sv_bf0e8f32ffe04ef4872947c05e5a75d9.Services;

// Submission records
public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

// Mutable form models used during editing
public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
}

@* Step progress bar: highlights current, checkmarks completed, dims future *@

<nav aria-label="Application steps">
    <ol class="step-indicator">
        @for (int i = 0; i < stepNames.Length; i++)
        {
            var stepNumber = i + 1;
            var isCompleted = CompletedSteps.Contains(stepNumber);
            var isCurrent = stepNumber == CurrentStep;
            var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

            <li class="@cssClass">
                @if (isCompleted)
                {
                    <button type="button" class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepNumber)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@stepNames[i]</span>
                    </button>
                }
                else
                {
                    <span class="step-content">
                        <span class="step-icon">@stepNumber</span>
                        <span class="step-label">@stepNames[i]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] stepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];
}

.step-indicator {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #dee2e6;
    position: relative;
}

.step.current {
    border-bottom-color: #0d6efd;
    font-weight: 600;
}

.step.completed {
    border-bottom-color: #198754;
}

.step.future {
    opacity: 0.5;
}

.step-button {
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    color: #198754;
    font: inherit;
    width: 100%;
}

.step-button:hover {
    text-decoration: underline;
}

.step-content {
    display: inline;
}

.step-icon {
    display: block;
    font-size: 1.25rem;
    margin-bottom: 0.25rem;
}

.step-label {
    font-size: 0.85rem;
}

@using sv_bf0e8f32ffe04ef4872947c05e5a75d9.Services

<h3>Personal Information</h3>

@if (Errors.Count > 0)
{
    <div class="alert alert-danger">
        <ul class="mb-0">
            @foreach (var error in Errors)
            {
                <li>@error</li>
            }
        </ul>
    </div>
}

<div class="mb-3">
    <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
    <input id="fullName" type="text" class="form-control" @bind="Model.FullName" />
</div>

<div class="mb-3">
    <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
    <input id="email" type="email" class="form-control" @bind="Model.Email" />
</div>

<div class="mb-3">
    <label for="phone" class="form-label">Phone <span class="text-danger">*</span></label>
    <input id="phone" type="tel" class="form-control" @bind="Model.Phone" />
</div>

<div class="mb-3">
    <label for="address" class="form-label">Address <span class="text-danger">*</span></label>
    <textarea id="address" class="form-control" rows="2" @bind="Model.Address"></textarea>
</div>

<div class="d-flex justify-content-end">
    <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter] public List<string> Errors { get; set; } = new();
    [Parameter] public bool IsValidating { get; set; }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

@using sv_bf0e8f32ffe04ef4872947c05e5a75d9.Services

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h5 class="card-title mb-0">Position @Index</h5>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row mb-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Entry.Company" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Entry.Title" />
            </div>
        </div>

        <div class="row mb-3">
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" @bind="Entry.StartDate" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input type="checkbox" class="form-check-input" id="current-@Index" @bind="Entry.IsCurrent"
                        @bind:after="HandleCurrentChanged" />
                    <label class="form-check-label" for="current-@Index">Currently working here</label>
                </div>
            </div>
        </div>

        <div class="mb-0">
            <label class="form-label">Description</label>
            <textarea class="form-control" rows="3" @bind="Entry.Description"></textarea>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void HandleCurrentChanged()
    {
        if (Entry.IsCurrent)
        {
            Entry.EndDate = null;
        }
    }
}

@using sv_bf0e8f32ffe04ef4872947c05e5a75d9.Services

<h3>Work History</h3>

@if (Errors.Count > 0)
{
    <div class="alert alert-danger">
        <ul class="mb-0">
            @foreach (var error in Errors)
            {
                <li>@error</li>
            }
        </ul>
    </div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryEditor Entry="Entries[index]"
                     Index="index + 1"
                     CanRemove="Entries.Count > 1"
                     OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter] public List<string> Errors { get; set; } = new();

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

@using sv_bf0e8f32ffe04ef4872947c05e5a75d9.Services

<h3>References</h3>

@if (Errors.Count > 0)
{
    <div class="alert alert-danger">
        <ul class="mb-0">
            @foreach (var error in Errors)
            {
                <li>@error</li>
            }
        </ul>
    </div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceEditor Reference="References[index]"
                     Index="index + 1"
                     CanRemove="References.Count > 2"
                     OnRemove="() => RemoveReference(index)" />
}

@if (References.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter] public List<string> Errors { get; set; } = new();

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

@using sv_bf0e8f32ffe04ef4872947c05e5a75d9.Services

<h3>Review &amp; Submit</h3>

@if (!string.IsNullOrEmpty(SubmitError))
{
    <div class="alert alert-danger">@SubmitError</div>
}

<!-- Personal Info -->
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Personal Information</strong>
        <button type="button" class="btn btn-link btn-sm p-0" @onclick='() => OnEditStep.InvokeAsync(1)'>Edit</button>
    </div>
    <div class="card-body">
        <dl class="row mb-0">
            <dt class="col-sm-3">Full Name</dt>
            <dd class="col-sm-9">@PersonalInfo.FullName</dd>
            <dt class="col-sm-3">Email</dt>
            <dd class="col-sm-9">@PersonalInfo.Email</dd>
            <dt class="col-sm-3">Phone</dt>
            <dd class="col-sm-9">@PersonalInfo.Phone</dd>
            <dt class="col-sm-3">Address</dt>
            <dd class="col-sm-9">@PersonalInfo.Address</dd>
        </dl>
    </div>
</div>

<!-- Work History -->
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Work History</strong>
        <button type="button" class="btn btn-link btn-sm p-0" @onclick='() => OnEditStep.InvokeAsync(2)'>Edit</button>
    </div>
    <div class="card-body">
        @foreach (var entry in WorkEntries)
        {
            <div class="mb-3 pb-3 border-bottom last-no-border">
                <h6>@entry.Title at @entry.Company</h6>
                <p class="text-muted mb-1">
                    @entry.StartDate?.ToString("MMM yyyy")
                    &ndash;
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                </p>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="mb-0">@entry.Description</p>
                }
            </div>
        }
    </div>
</div>

<!-- References -->
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>References</strong>
        <button type="button" class="btn btn-link btn-sm p-0" @onclick='() => OnEditStep.InvokeAsync(3)'>Edit</button>
    </div>
    <div class="card-body">
        @foreach (var reference in References)
        {
            <div class="mb-2">
                <strong>@reference.Name</strong> — @reference.Relationship<br />
                <span class="text-muted">@reference.Email · @reference.Phone</span>
            </div>
        }
    </div>
</div>

<!-- Cover Letter -->
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Cover Letter</strong>
        <button type="button" class="btn btn-link btn-sm p-0" @onclick='() => OnEditStep.InvokeAsync(4)'>Edit</button>
    </div>
    <div class="card-body">
        <p style="white-space: pre-wrap;">@CoverLetter</p>
    </div>
</div>

<div class="d-flex justify-content-between">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button type="button" class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
        @if (IsSubmitting)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Submitting…</span>
        }
        else
        {
            <span>Submit Application</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public string? SubmitError { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
}

@page "/apply"
@rendermode InteractiveServer
@using sv_bf0e8f32ffe04ef4872947c05e5a75d9.Services
@using sv_bf0e8f32ffe04ef4872947c05e5a75d9.Components.JobApplication
@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @if (isSubmitted)
    {
        <div class="alert alert-success text-center py-5">
            <h2 class="mb-3">&#10003; Application Submitted!</h2>
            <p class="lead">Your application has been received.</p>
            <p class="fs-4">Application ID: <strong>@applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep"
                       CompletedSteps="completedSteps"
                       OnStepClicked="GoToStep" />

        @switch (currentStep)
        {
            case 1:
                <PersonalInfoStep Model="personalInfo"
                                  Errors="errors"
                                  IsValidating="isValidatingEmail"
                                  OnNext="HandlePersonalInfoNext" />
                break;
            case 2:
                <WorkHistoryStep Entries="workEntries"
                                 Errors="errors"
                                 OnNext="HandleWorkHistoryNext"
                                 OnBack="GoBack" />
                break;
            case 3:
                <ReferencesStep References="references"
                                Errors="errors"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;
            case 4:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 CoverLetterChanged="value => coverLetter = value"
                                 Errors="errors"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;
            case 5:
                <ReviewStep PersonalInfo="personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="@coverLetter"
                            IsSubmitting="isSubmitting"
                            SubmitError="@submitError"
                            OnSubmit="HandleSubmit"
                            OnBack="GoBack"
                            OnEditStep="GoToStep" />
                break;
        }
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();
    private List<string> errors = new();

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = "";

    // Submission state
    private bool isValidatingEmail;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
        {
            errors.Clear();
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 1)
        {
            errors.Clear();
            currentStep--;
        }
    }

    private void AdvanceToNext()
    {
        completedSteps.Add(currentStep);
        errors.Clear();
        currentStep++;
    }

    // Step 1 validation
    private async Task HandlePersonalInfoNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(personalInfo.FullName))
            errors.Add("Full name is required.");
        if (string.IsNullOrWhiteSpace(personalInfo.Email))
            errors.Add("Email is required.");
        if (string.IsNullOrWhiteSpace(personalInfo.Phone))
            errors.Add("Phone is required.");
        if (string.IsNullOrWhiteSpace(personalInfo.Address))
            errors.Add("Address is required.");

        if (errors.Count > 0)
            return;

        isValidatingEmail = true;
        try
        {
            var isValid = await AppService.ValidateEmailAsync(personalInfo.Email);
            if (!isValid)
            {
                errors.Add("The email address is not valid.");
                return;
            }
        }
        catch
        {
            errors.Add("Unable to validate email. Please try again.");
            return;
        }
        finally
        {
            isValidatingEmail = false;
        }

        AdvanceToNext();
    }

    // Step 2 validation
    private Task HandleWorkHistoryNext()
    {
        errors.Clear();

        for (int i = 0; i < workEntries.Count; i++)
        {
            var entry = workEntries[i];
            var pos = i + 1;

            if (string.IsNullOrWhiteSpace(entry.Company))
                errors.Add($"Position {pos}: Company name is required.");
            if (string.IsNullOrWhiteSpace(entry.Title))
                errors.Add($"Position {pos}: Job title is required.");
            if (entry.StartDate is null)
                errors.Add($"Position {pos}: Start date is required.");
        }

        if (errors.Count == 0)
            AdvanceToNext();

        return Task.CompletedTask;
    }

    // Step 3 validation
    private Task HandleReferencesNext()
    {
        errors.Clear();

        for (int i = 0; i < references.Count; i++)
        {
            var r = references[i];
            var num = i + 1;

            if (string.IsNullOrWhiteSpace(r.Name))
                errors.Add($"Reference {num}: Name is required.");
            if (string.IsNullOrWhiteSpace(r.Relationship))
                errors.Add($"Reference {num}: Relationship is required.");
            if (string.IsNullOrWhiteSpace(r.Email))
                errors.Add($"Reference {num}: Email is required.");
            if (string.IsNullOrWhiteSpace(r.Phone))
                errors.Add($"Reference {num}: Phone is required.");
        }

        if (errors.Count == 0)
            AdvanceToNext();

        return Task.CompletedTask;
    }

    // Step 4 validation
    private Task HandleCoverLetterNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(coverLetter))
            errors.Add("Cover letter is required.");

        if (errors.Count == 0)
            AdvanceToNext();

        return Task.CompletedTask;
    }

    // Step 5 submission
    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate!.Value, e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            applicationId = await AppService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

namespace sv_bf0e8f32ffe04ef4872947c05e5a75d9.Services;

// Submission records
public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

// Mutable form models used during editing
