.step-indicator {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #dee2e6;
    position: relative;
}

.step.current {
    border-bottom-color: #0d6efd;
    font-weight: 600;
}

.step.completed {
    border-bottom-color: #198754;
}

.step.future {
    opacity: 0.5;
}

.step-button {
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    color: #198754;
    font: inherit;
    width: 100%;
}

.step-button:hover {
    text-decoration: underline;
}

.step-content {
    display: inline;
}

.step-icon {
    display: block;
    font-size: 1.25rem;
    margin-bottom: 0.25rem;
}

.step-label {
    font-size: 0.85rem;
}

